--- a/Sources/Clinic/Cart.swift
+++ b/Sources/Clinic/Cart.swift
@@ -6,17 +6,31 @@ struct Service {
     let priceKop: Int
 }

 struct Cart {

     var services: [Service] = []
     var discountPercent: Int = 0

-    var totalKop: Int {
-        services.reduce(0) { $0 + $1.priceKop }
+    var total: Double {
+        let sum = services.reduce(0.0) { $0 + Double($1.priceKop) / 100 }
+        let discount = sum * Double(discountPercent) / 100
+
+        return sum - discount
+    }
+
+    var formatted: String {
+        String(format: "%.2f ₽", total)
+    }
+
+    mutating func add(_ service: Service) {
+        services.append(service)
     }
 }
